exec((__import__('pathlib').Path(__file__).parent/'commerce-pages.py').read_text(encoding='utf-8').split("contact=intro")[0])
version='2026-09-09-draft-v1'
for p in plans:
 for kind in ['business','consumer']:
  audience='事業者向け' if kind=='business' else '一般消費者向け'
  clauses=[
   ('1. 契約の当事者と適用範囲',f'本書は、依頼者（以下「お客様」）と、Web制作事務所クルーアセントの運営者（以下「当方」）が締結する「{p["name"]}プラン」のWebサイト制作契約の条件を定めます。正式な契約当事者名、住所、連絡先、契約日、個別見積番号を末尾に記載します。'+('お客様は、本契約を法人・個人事業主として、事業のために締結します。個人名義であっても事業目的の場合はこちらの区分を想定します。' if kind=='business' else 'お客様は、本契約を事業目的以外で締結する個人とします。消費者契約法その他の強行法規に反する内容がある場合、その法令を優先します。')),
   ('2. 契約の成立と優先順位','ご相談・診断・ヒアリングシートの送信だけで制作契約は成立しません。制作範囲・金額・提供時期を記載した個別見積書と本契約書を双方が確認し、お客様の申込みを当方が承諾したときに契約が成立します。個別合意書、本契約書の順に適用しますが、強行法規に優先することはできません。追加変更はメール等の記録に残る方法で双方が合意します。'),
   ('3. 制作範囲',f'対象は{p["pages"]}のWebサイトです。文章対応は「{p["text"]}」、画像対応は「{p["images"]}」です。基本構成、スマートフォン対応、問い合わせフォーム・導線、title・description・OGP等の基本SEO設定、公開作業を含みます。各ページ名・必要機能・納品形式・対応ブラウザ・対象URLは個別見積書で確定します。'+('Webサイト内で使う簡易ロゴタイプ1案、ファビコン・OGP用ロゴ、外部サービスへの導線、GA4・Search Consoleの初期設定支援を含みます。各アカウント・権限はお客様にご準備いただきます。' if p['id']=='omakase' else '本格的なコピーライティング、取材、ロゴ・ブランド設計、撮影は含みません。')+'SEO記事作成、SNS運用、複雑な予約・決済機能、公開後の継続修正、外部サービス費用は本契約に自動では含まれません。'),
   ('4. 制作代金・支払い',f'制作費の基準額は{p["price"]:,}円です。税区分は未確定のため、本書の金額を確定した契約金額として使用する前に、税込総額・税額・支払方法を個別見積書へ記載します。基準額が税込の場合、着手金50%は{p["price"]//2:,}円、残金50%は{p["price"]//2:,}円です。着手金は制作着手前、残金は公開または納品前に支払います。支払期日は個別見積書で確定します。Shopifyで支払う場合は、専用リンクに表示された金額と最終確認画面の総額を確認してください。外部サービス費・振込手数料等の負担は発生前に明示します。'),
   ('5. 制作日程と協力',f'納期の目安は、必要な原稿・写真等がそろってから{p["weeks"]}です。具体的な着手日・初稿提出日・最終納期は個別見積書で合意します。お客様は、必要な素材、アカウント権限、確認回答を合意した日程で提供します。素材遅延・仕様変更等で日程調整が必要になった場合は、理由と新しい日程を協議し、当方だけで一方的に追加費用や納期を変更しません。'),
   ('6. 修正と追加作業',f'本プランの修正は{p["revisions"]}の範囲を想定し、契約時に具体的な回数を確定します。「1回」は、まとめて提出された修正依頼1セットを指します。合意した仕様からの不一致や当方に起因する不具合の是正は、この修正回数とは別に扱います。ページ追加、大幅な構成変更、デザイン全面変更等は内容・費用・日程を提示し、お客様の承認を得てから実施します。'),
   ('7. 確認・納品と不具合への対応','当方は初稿・最終稿を提示し、お客様は個別合意した確認期間内に内容をご確認ください。期間内に連絡がないことだけを理由に検収完了とはみなしません。確認が遅れる場合は日程を協議します。残金の支払い確認後に、合意した形式でデータを納品、または公開します。合意仕様との不一致・契約不適合がある場合は、内容・原因・適用法令に応じて修補等を協議し、お客様が法令上有する権利を不当に制限しません。'),
   ('8. 支給素材・制作物の権利','お客様は、支給する文章・写真・ロゴ等について、本制作・公開に必要な利用権限を確保します。当方は権利上の懸念を認識した場合、掲載を保留して確認します。当方が本契約のため新たに制作し著作権を保有する固有の成果物の著作権（著作権法第27条・第28条の権利を含む）は、代金全額の支払い後にお客様へ移転する条件とします。当方は合意したサイト利用の範囲で著作者人格権を行使しません。既存の汎用プログラム、診断エンジン、第三者素材、フォント、ライブラリ等は移転対象から除外し、それぞれのライセンスが適用されます。当方が保有する既存素材については、納品サイトの利用・保守に必要な範囲で継続利用を許諾します。生成画像等は独占性や著作権の成立を一律に保証せず、内容と利用条件を公開前に確認します。'),
   ('9. 実績掲載・秘密保持','お客様の名称、URL、画面写真を当方の実績として公開する場合は、対象と範囲を示して別途同意を得ます。実績掲載の同意は制作の必須条件ではありません。契約の検討・履行により知った非公開情報は、履行に必要な範囲と法令上必要な場合を除き、相手方の同意なく第三者へ開示しません。外部委託が必要な場合は、秘密保持と適切な監督を行います。'),
   ('10. 個人情報・アカウント情報','個人情報は、相談、制作、連絡、予約、契約、請求に必要な目的で取り扱います。外部サービスへの委託や保存期間は、実際の運用と一致するプライバシーポリシーに記載します。カード情報はShopifyの決済画面で入力し、当方のヒアリングシートへ送信しないでください。アカウントのパスワードをシートに記入せず、必要最小限の招待権限などを利用します。'),
   ('11. お客様からの解除・精算','解除を希望する場合は、末尾記載の連絡先へメール等の記録に残る方法でお知らせください。制作着手前は、お客様が事前承認した取消不能な実費がある場合を除き、受領済み金額を返金します。制作着手後は、完了した作業に対応する対価と合理的な取消不能費用の内訳を明示し、未実施部分に対応する前払い金を返金する方法で精算します。進行中の成果物は、精算対象と権利関係を確認したうえで引き渡します。返金額・返金方法・返金予定日は記録に残る方法で案内します。'+('違約金を当然に制作費全額とすることはなく、契約の進行状況と適用法令に応じて協議します。' if kind=='business' else '解約料・違約金等の合計は、同種の契約の解除に伴い当方に生ずべき平均的な損害の額その他法令上認められる範囲を超えません。計算の根拠について、お客様から求められた場合は説明に努めます。')),
   ('12. 当方の不履行・解除','当方の責任で制作の継続・履行ができない場合は、未履行部分の対価を返金し、既存成果物の扱いと必要な是正・損害の扱いを適用法令に従って協議します。「着手金の80%まで」等の一律の返金上限は設けません。重大な契約違反がある場合は、法令上催告が不要な場合を除いて合理的な是正期間を設け、それでも是正されない場合に解除できます。'),
   ('13. 責任の範囲','当方は合意した作業を適切に行いますが、検索順位、売上、問い合わせ件数、外部サービスの継続や仕様を保証しません。この非保証は、当方の契約上の履行義務や法令上の責任を免除する趣旨ではありません。第三者サービスの障害は原因と対応可能な範囲を確認して連絡します。'+('損害の範囲・賠償額は、原因、帰責性、予見可能性および適用法令に照らして協議します。当方の故意・重大な過失による責任を免除しません。' if kind=='business' else '当方の債務不履行・不法行為による損害賠償責任の全部を免除する条項、故意・重大な過失による責任を一部免除する条項、責任の有無や限度を当方だけで決める条項は設けません。お客様の法定の解除権等を排除しません。')),
   ('14. 公開・管理と契約終了後','制作費はWebサイトの制作に対する対価です。月額5,500円または年額50,000円の公開・管理プランは任意の別契約であり、自動加入・自動課金しません。利用する場合は、税区分、サーバー・ドメインの名義と費用、作業範囲、更新、解約、データ保管・移管方法を別途合意します。管理契約を利用しない場合も、公開環境・権限・納品方法を制作契約時に確認します。'),
   ('15. 準拠法・協議','本契約の準拠法は日本法とします。定めのない事項や解釈上の疑義は誠実に協議します。合意管轄裁判所は、当事者の所在地と取引実態に照らし、契約前に確認します。未記入の場合は法令が定める管轄によります。'+('' if kind=='business' else '消費者の利益を一方的に害する管轄合意は行わず、消費者契約法その他適用法令による保護を妨げません。'))]
  title=f'Webサイト制作契約書 / {p["name"]}プラン / {audience}'
  note='本書は確認用の草案です。正式な当事者情報、税込総額、制作仕様、納期、検収期間、連絡先を確定し、日本法の専門家による確認を経てから使用してください。'
  signatures='''<section class="ca-signatures"><div><h2>お客様（依頼者）</h2><p>氏名・法人名：________________________<br>代表者・担当者：______________________<br>住所：______________________________<br>メール：____________________________<br>署名：______________________________</p></div><div><h2>当方（受託者）</h2><p>屋号：クルーアセント<br>正式氏名・法人名：____________________<br>住所：______________________________<br>メール・電話：_______________________<br>署名：______________________________</p></div></section><p>契約日：______年____月____日<br>個別見積番号：_______________________<br>税込総額：_______________円（うち税額：_______________円）<br>着手金・期限：_______________________<br>残金・期限：_________________________<br>納期・検収期間：______________________</p>'''
  body=intro('AGREEMENT / '+audience,p['name']+'プラン<br>Webサイト制作契約書',audience+' ／ 契約版 '+version)+f'<article class="wrap ca-content ca-legal"><div class="ca-notice ca-notice-warn">{note}</div><div class="ca-actions ca-no-print"><button class="ca-button" type="button" id="print-contract">印刷・PDF保存 ↓</button><a href="{p["id"]}-{kind}.md" download>Markdown版を保存</a></div>'+''.join(f'<section><h2>{h}</h2><p>{text}</p></section>' for h,text in clauses)+signatures+'</article>'
  doc=page(title,note,body,script='contract.js')
  doc=doc.replace('href="assets/','href="../assets/').replace('src="assets/','src="../assets/')
  # Shared navigation is one directory above; leave the MD download local.
  doc=re.sub(r'href="((?:index|services|plans|types|about|contact|booking|process|management|diagnosis|guide|faq|works|contracts|privacy|terms|commercial-transactions)\.html)',r'href="../\1',doc)
  write(f'contracts/{p["id"]}-{kind}.html',doc)
  md='# '+title+'\n\n**確認用草案 / '+version+'**\n\n'+note+'\n\n'+'\n\n'.join('## '+h+'\n\n'+t for h,t in clauses)+'\n\n## 個別合意・署名欄\n\n- 契約日：\n- 見積番号：\n- 依頼者の氏名・法人名／住所／連絡先／署名：\n- 受託者の正式氏名・法人名／住所／連絡先／署名：\n- 制作仕様・対象ページ・納品形式・対応ブラウザ：\n- 税込総額／税額／着手金／残金：\n- 支払期日／制作納期／検収期間：\n- 実績掲載の可否・範囲（任意）：\n'
  write(f'contracts/{p["id"]}-{kind}.md',md)
terms=[('本サイトについて','クルーアセントは、Webサイトで優先する方向を整理する診断と、Webサイト制作の相談窓口を提供します。診断、無料ヒアリングシート、無料予約だけで制作契約は成立しません。'),('Web診断36の位置づけ','Web診断36は、回答時点のWebサイトに関する希望を整理するための参考情報です。心理検査、性格診断、経営診断ではなく、事業の優劣や成果を判定するものではありません。診断結果に優劣はなく、結果どおりに制作する義務はありません。'),('診断データの保存','診断の回答はブラウザのローカルストレージに保存し、原則30日間で再開対象から外れます。診断の生の回答はサーバーへ自動送信しません。診断結果をヒアリングシートに記入して送信した場合、その記入内容は相談対応のために保存します。共有端末での利用後は、ブラウザのサイトデータを削除できます。'),('無料相談と予約','ヒアリングシートは相談対応のための受付です。予約は公開された1時間枠につき1名です。予約完了時に日時・受付番号・取消リンクを表示します。予約の変更は、取消後に別枠をお選びください。予約が競合した場合は、先にサーバーで確定した予約が優先されます。無断で他人の情報を登録したり、不要な枠を大量に予約したりする行為は禁止します。'),('制作契約と支払い','制作範囲、価格、提供時期、支払い、権利、解除等は、双方で確認した個別見積書と制作契約書によります。着手金50%・残金50%を基本とし、相談中に自動課金することはありません。契約書一覧からプラン別・ご利用区分別の草案を確認できます。'),('権利・禁止行為','サイト内の文章・設計・プログラム・画像等について、権利が成立する範囲では当方または正当な権利者に帰属します。法令上認められる引用等を除き、権利を侵害する転載・再販売を禁止します。不正アクセス、予約・決済の妨害、第三者へのなりすましは禁止します。'),('情報・責任について','掲載情報は適切に保つよう努めますが、更新・変更があり得ます。診断結果や一般記事は個別の事業成果を保証しません。外部サービスには各社の利用条件が適用されます。この説明は、当方の故意・過失による法令上の責任を一律に免除したり、消費者の法定の権利を制限したりするものではありません。'),('規約の変更と問い合わせ','重要な変更がある場合は、サイト上で内容と適用時期を案内します。既に成立した制作契約に不利益な変更を一方的に適用しません。正式事業者名・問い合わせ先・施行日は、公開前に確定して本ページへ表示します。')]
privacy=[('確認用サイトの取り扱い','このページは実装に合わせた確認用の草案です。現在の確認用サイトでは、送信された相談・予約の内容をデータベースへ保存します。動作確認にはテスト用の情報をご使用ください。本番の受付開始前に、事業者名、連絡先、保管期間、実際に利用する委託先を確定します。'),('取得する情報','相談フォームでは氏名、メールアドレス、事業情報、希望内容、任意で記入した診断結果等を取得します。予約では氏名、メールアドレス、相談内容、予約日時、同意日時・適用する方針の版を保存します。契約・決済では見積内容、利用区分、同意の記録、決済参照情報を扱います。スパム対策のため、接続元IP等から作ったハッシュ値を一定時間の送信回数制限に使います。'),('利用目的','お問い合わせへの回答、ヒアリング予約の管理と連絡、見積もり・契約・制作業務、請求と支払い確認、不正利用の防止のために利用します。無料診断やシートの利用者を、同意なく営業メールの購読者として登録しません。'),('保存場所と外部サービス','確認用の公開環境はSites上で動作し、サーバー処理・データ保存にはCloudflare Workers・D1を使用する構成です。ローカル確認環境では端末上のSQLiteを使用します。Shopifyの決済接続を有効にした場合、請求用メールアドレスと注文参照情報をShopifyへ送信します。カード情報はShopifyの画面で入力され、このサイトのフォームには保存しません。Resendを有効にした場合は、メールアドレスと受付・予約の案内内容をメール送信のために取り扱わせます。実際の契約先、所在国・制度情報等の確認が必要な場合は、公開前に追記します。'),('ブラウザ保存・Cookie','Web診断36の回答は端末のローカルストレージに保存されます。ヒアリングシートの個人情報をブラウザの保存領域へ自動保存する実装は行っていません。管理者ログインには認証用Cookieを使います。サイト側のGA4等の解析は初期状態で無効です。Sitesの閲覧認証等は提供プラットフォームの条件にも従います。'),('安全管理','管理画面には認証を設け、利用者の情報を公開APIで一覧取得できない構成にしています。予約取消リンクはランダムな長い文字列を使用し、予約テーブルではそのハッシュを保存します。リンクを知る人は予約を確認・取消できるため、第三者へ共有しないでください。実運用での権限管理、バックアップ、端末保護、委託先管理等の詳細は運用開始前に確認します。'),('保管期間・削除','問い合わせ、予約、契約・会計に関する情報は、それぞれの対応目的と適用法令に応じた保管期間を公開前に確定します。現段階では、期限に応じて全データを自動削除する機能はありません。保管期間と削除手順を確定せずに、本番の個人情報受付を開始しない運用とします。不要となった情報は、法令上保存が必要なものを除き適切に削除します。'),('開示・訂正・利用停止等','ご本人からの開示、訂正、削除、利用停止等のお申し出には、本人確認のうえ、個人情報保護法等に従って対応します。受付窓口、本人確認方法、必要な手数料の有無は公開前に確定します。予約の取り消しは予約の停止を意味し、保存済みの記録の削除とは異なります。'),('事業者・問い合わせ窓口','屋号：クルーアセント。正式氏名・法人名、住所、個人情報の問い合わせ先、施行日：公開前に確定。これらの確定情報を掲示し、実際の外部サービス利用と本文を一致させてから本番運用を開始します。')]
commercial=[('事業者情報','屋号：クルーアセント。正式な販売・役務提供事業者名、運営責任者、所在地、電話番号、メールアドレス：公開前に確定。現時点は確認用のため、決済を停止しています。'),('販売価格・役務の対価','制作費の基準額：はじめて80,000円、シンプル120,000円、標準150,000円、おまかせ220,000円。税区分は未確定です。本番公開・決済開始前に税込総額を確定し、プラン、契約書、見積書、Shopify商品の金額を一致させます。'),('代金以外の必要料金','ドメイン・サーバー、追加素材、外部有料サービス、振込手数料等が必要になる場合は、金額または算定方法・負担者を契約前に明示します。追加1ページ20,000円〜、本格ロゴ制作15,000円〜、画像追加準備5,000円〜は基準額で、税区分と内容は個別見積書で確定します。'),('支払方法と支払時期','着手前50%、公開または納品前50%を基本とし、個別見積書に支払期日を明示します。Shopify決済の接続を予定しています。利用可能な決済手段は、接続したShopifyストアの最終決済画面に表示します。接続・表示確認前に利用可能と断定しません。'),('役務の提供時期','必要素材の提出後から、はじめて1〜2週間、シンプル2〜3週間、標準3〜4週間、おまかせ4〜6週間が目安です。具体的な提供時期は契約前に個別見積書へ記載します。素材提出や仕様変更により調整が必要な場合は双方で協議します。'),('申込みの撤回・解除・返金','相談・無料診断・ヒアリングシートの送信に料金は発生しません。制作契約後の解除は、正式な連絡先へ記録に残る方法で申し出ます。着手前は事前承認された取消不能な実費を除き返金します。着手後は完了作業と合理的な取消不能費用を明示して精算し、未実施部分の前払い金を返金します。一般消費者向けの解約料等は法令上認められる範囲を超えません。当方の責任による不履行に一律の返金上限は設けません。'),('契約不適合への対応','合意した仕様との不一致や当方に起因する不具合は、通常の希望修正回数とは別に、原因・内容・適用法令に応じて是正等を協議します。法令上有する解除・損害賠償等の権利を排除するものではありません。'),('申込期間・数量等','制作プランは1案件単位です。合意済みの支払いリンクは発行から7日間有効とし、画面に期限を表示します。期限後は再確認して発行します。無料ヒアリングの予約は1時間につき1名で、公開されている予約枠から選択します。予約枠の取得は制作契約の購入を意味しません。'),('任意の公開・管理プラン','月額5,500円または年額50,000円を基準額とする別契約です。制作プランの決済で自動加入・自動更新しません。税区分、初月・翌月分の請求、年額前払い、更新、解約連絡期限、返金、ドメイン費、未払い時の措置は別途契約で確定し、申込み前に明示します。')]
for filename,title,parts in [('terms.html','利用規約',terms),('privacy.html','プライバシーポリシー',privacy),('commercial-transactions.html','特定商取引法に基づく表記',commercial)]:
 body=intro('POLICIES & INFORMATION',title,'事業者情報・運用条件の確定前の確認用原稿です。')+'<article class="wrap ca-content ca-legal">'+''.join('<section><h2>'+h+'</h2><p>'+t+'</p></section>' for h,t in parts)+'<a class="ca-text-link" href="contracts.html">制作契約書とお支払い内容を見る →</a></article>'
 write(filename,page(title,title+'の確認用原稿。',body))
write('assets/js/contract.js',"document.getElementById('print-contract')?.addEventListener('click',()=>window.print());\n")
